function findAnagrams(s, p) {
  if (s.length < p.length) return [];
  const pCount = {};
  const sCount = {};
  for (let i = 0; i < p.length; i++) {
    pCount[p[i]] = (pCount[p[i]] || 0) + 1;
  }
  const result = [];
  const k = p.length;
  for (let i = 0; i < s.length; i++) {
    const char = s[i];
    sCount[char] = (sCount[char] || 0) + 1;
    if (i >= k) {
      const out = s[i - k];
      if (sCount[out] === 1) delete sCount[out];
      else sCount[out]--;
    }
    if (i >= k - 1) {
      let match = true;
      for (const key of Object.keys(pCount)) {
        if (sCount[key] !== pCount[key]) {
          match = false;
          break;
        }
      }
      if (match && Object.keys(sCount).length === Object.keys(pCount).length) {
        result.push(i - k + 1);
      }
    }
  }
  return result;
}

